typedef struct {
  atomic_bool valid;
  atomic_bool busy;
  int frame;
} Page;

void fault(Page *p, int page_num) {
  bool expected = false;
  if (atomic_compare_exchange_strong(&p->valid, &expected, true)) {
    p->frame = allocate_frame();
    if (load_or_zero(p->frame, page_num)) {
      // success
    } else {
      // handle error
    }
  } else {
    // wait for valid
  }
}
```

